1	package api
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"io"
10		"net/http"
11		"net/url"
12		"strings"
13	
14		"github.com/entireio/cli/cmd/entire/cli/versioninfo"
15	)
16	
17	const (
18		maxResponseBytes = 16 << 20
19	)
20	
21	// Client is an authenticated HTTP client for the Entire API.
22	// It attaches the bearer token to all outgoing requests via the Authorization header.
23	type Client struct {
24		httpClient *http.Client
25		baseURL    string
26	
27		// trailRoutes maps the legacy trail-id prefix used internally by the CLI's
28		// review helpers to the repo/number-addressed entire-api route. It lets the
29		// review command keep passing a stable trail ID through its domain helpers
30		// while requests go to the new cell API, whose public routes are addressed
31		// as /trails/{host}/{owner}/{repo}/{number}.
32		trailRoutes map[string]string
33	
34		// authSessionsPath is the base path for entire-core's login-session
35		// endpoints (list / revoke / current). Set via WithAuthSessionsPath when the
36		// client targets the auth host; empty otherwise, and the session methods
37		// error out if called against an empty path.
38		authSessionsPath string
39	}
40	
41	// WithAuthSessionsPath sets the base path used by ListAuthSessions,
42	// RevokeCurrentAuthSession, and RevokeAuthSession. Returns the receiver for chaining
43	// at construction:
44	//
45	//	c := api.NewClientWithBaseURL(token, base).WithAuthSessionsPath(p)
46	func (c *Client) WithAuthSessionsPath(path string) *Client {
47		c.authSessionsPath = path
48		return c
49	}
50	
51	// NewClient creates a new authenticated API client with an explicit bearer
52	// token, targeting the data API base URL (BaseURL()).
53	func NewClient(token string) *Client {
54		return NewClientWithBaseURL(token, BaseURL())
55	}
56	
57	// NewClientWithBaseURL creates a new authenticated API client targeting an
58	// explicit base URL. Use this for endpoints that live on a login server
59	// rather than the data API (e.g. auth-session management).
60	func NewClientWithBaseURL(token, baseURL string) *Client {
61		return &Client{
62			httpClient: &http.Client{
63				Transport: &bearerTransport{
64					token: token,
65					base:  http.DefaultTransport,
66				},
67				// A cross-host redirect must never carry the Entire bearer to
68				// another origin; refuse it rather than follow it. Same-origin
69				// requests are guaranteed by the base-host check in do().
70				CheckRedirect: rejectCrossHostRedirect,
71			},
72			baseURL: baseURL,
73		}
74	}
75	
76	// rejectCrossHostRedirect stops a redirect chain from leaving the origin the
77	// client was built for. Same-host redirects (e.g. a trailing-slash normalize)
78	// still follow, up to Go's usual 10-hop cap.
79	func rejectCrossHostRedirect(req *http.Request, via []*http.Request) error {
80		if len(via) >= 10 {
81			return errors.New("stopped after 10 redirects")
82		}
83		if len(via) > 0 && !strings.EqualFold(req.URL.Host, via[0].URL.Host) {
84			return fmt.Errorf("refusing redirect to a different host (%s → %s): the Entire bearer must not leave its origin", via[0].URL.Host, req.URL.Host)
85		}
86		return nil
87	}
88	
89	// requireSameHost rejects an endpoint whose host differs from the base URL's.
90	// It guards the direct case (a path that resolved to another host); redirects
91	// are handled by rejectCrossHostRedirect.
92	func requireSameHost(baseURL, endpoint string) error {
93		b, err := url.Parse(baseURL)
94		if err != nil {
95			return fmt.Errorf("parse base URL: %w", err)
96		}
97		e, err := url.Parse(endpoint)
98		if err != nil {
99			return fmt.Errorf("parse endpoint URL: %w", err)
100		}
101		if !strings.EqualFold(b.Host, e.Host) {
102			return fmt.Errorf("refusing to send an authenticated request to %q, which is not the API host %q", e.Host, b.Host)
103		}
104		return nil
105	}
106	
107	// bearerTransport is an http.RoundTripper that injects the Authorization header.
108	//
109	// The token is only ever sent to the client's base host: do() rejects a request
110	// URL whose host differs from the base, and CheckRedirect refuses a cross-host
111	// redirect, so every request this transport sees is same-origin as the base.
112	//
113	// When token is empty, the Authorization header is omitted (rather than sent
114	// as a malformed "Authorization: Bearer "). This supports endpoints like
115	// recap that deliberately want the unauthenticated request to reach the
116	// server so it can return a typed 401 — callers that want a local fast-fail
117	// for missing auth should check ErrNotLoggedIn at construction time, not
118	// rely on the transport.
119	type bearerTransport struct {
120		token string
121		base  http.RoundTripper
122	}
123	
124	func (t *bearerTransport) RoundTrip(req *http.Request) (*http.Response, error) {
125		// Clone the request to avoid mutating the caller's request.
126		r := req.Clone(req.Context())
127		if t.token != "" {
128			r.Header.Set("Authorization", "Bearer "+t.token)
129		}
130		r.Header.Set("User-Agent", versioninfo.UserAgent())
131		if r.Header.Get("Accept") == "" {
132			r.Header.Set("Accept", "application/json")
133		}
134		resp, err := t.base.RoundTrip(r)
135		if err != nil {
136			return nil, fmt.Errorf("round trip: %w", err)
137		}
138		return resp, nil
139	}
140	
141	// Get sends an authenticated GET request to the given API-relative path.
142	func (c *Client) Get(ctx context.Context, path string) (*http.Response, error) {
143		return c.do(ctx, http.MethodGet, path, nil, nil)
144	}
145	
146	// GetStream sends an authenticated GET request with optional extra request
147	// headers (e.g. Accept: text/event-stream, Last-Event-ID) and returns the
148	// response with the body still open. Callers are responsible for reading and
149	// closing resp.Body. Intended for streaming endpoints such as Server-Sent
150	// Events; for normal JSON requests use Get.
151	func (c *Client) GetStream(ctx context.Context, path string, headers http.Header) (*http.Response, error) {
152		return c.do(ctx, http.MethodGet, path, nil, headers)
153	}
154	
155	// doJSON sends an authenticated request with an optional JSON-marshaled body.
156	func (c *Client) doJSON(ctx context.Context, method, path string, body any) (*http.Response, error) {
157		var reader io.Reader
158		if body != nil {
159			data, err := json.Marshal(body)
160			if err != nil {
161				return nil, fmt.Errorf("marshal request body: %w", err)
162			}
163			reader = bytes.NewReader(data)
164		}
165		return c.do(ctx, method, path, reader, nil)
166	}
167	
168	// Post sends an authenticated POST request with a JSON body to the given API-relative path.
169	func (c *Client) Post(ctx context.Context, path string, body any) (*http.Response, error) {
170		return c.doJSON(ctx, http.MethodPost, path, body)
171	}
172	
173	// Put sends an authenticated PUT request with a JSON body to the given API-relative path.
174	func (c *Client) Put(ctx context.Context, path string, body any) (*http.Response, error) {
175		return c.doJSON(ctx, http.MethodPut, path, body)
176	}
177	
178	// Patch sends an authenticated PATCH request with a JSON body to the given API-relative path.
179	func (c *Client) Patch(ctx context.Context, path string, body any) (*http.Response, error) {
180		return c.doJSON(ctx, http.MethodPatch, path, body)
181	}
182	
183	// Delete sends an authenticated DELETE request to the given API-relative path.
184	func (c *Client) Delete(ctx context.Context, path string) (*http.Response, error) {
185		return c.do(ctx, http.MethodDelete, path, nil, nil)
186	}
187	
188	// Request sends an authenticated request with an explicit method, optional
189	// extra headers, and an optional raw body. It's the general-purpose escape
190	// hatch behind `entire api`; prefer the typed verbs (Get/Post/…) for normal
191	// use. The bearer, User-Agent, and default Accept are still attached by the
192	// transport; a body defaults to Content-Type: application/json unless the
193	// caller supplies its own via headers.
194	func (c *Client) Request(ctx context.Context, method, path string, headers http.Header, body io.Reader) (*http.Response, error) {
195		return c.do(ctx, method, path, body, headers)
196	}
197	
198	// SetTrailRoute registers the entire-api base path for a resolved trail. The
199	// CLI's review/finding helpers historically build paths from the trail ID; the
200	// new backend addresses those same resources by repository and trail number.
201	func (c *Client) SetTrailRoute(trailID, path string) {
202		trailID = strings.TrimSpace(trailID)
203		path = strings.TrimRight(strings.TrimSpace(path), "/")
204		if trailID == "" || path == "" {
205			return
206		}
207		if c.trailRoutes == nil {
208			c.trailRoutes = make(map[string]string)
209		}
210		c.trailRoutes[url.PathEscape(trailID)] = path
211	}
212	
213	func (c *Client) rewriteTrailRoute(path string) string {
214		const prefix = "/api/v1/trails/"
215		if !strings.HasPrefix(path, prefix) || len(c.trailRoutes) == 0 {
216			return path
217		}
218		rest := strings.TrimPrefix(path, prefix)
219		id, suffix, _ := strings.Cut(rest, "/")
220		base, ok := c.trailRoutes[id]
221		if !ok {
222			return path
223		}
224		if suffix == "" {
225			return base
226		}
227		return base + "/" + suffix
